import socket
import subprocess
import sys
from datetime import datetime

def get_default_gateway():
    """Get the default gateway IP address."""
    try:
        # Use route command to get default gateway
        result = subprocess.run(['ip', 'route'], capture_output=True, text=True)
        if result.returncode == 0:
            for line in result.stdout.split('\n'):
                if 'default' in line or '0.0.0.0/0' in line:
                    parts = line.split()
                    if 'via' in line:
                        return parts[parts.index('via') + 1]

        # Alternative method using netstat
        result = subprocess.run(['netstat', '-rn'], capture_output=True, text=True)
        if result.returncode == 0:
            for line in result.stdout.split('\n'):
                if 'default' in line or '0.0.0.0' in line:
                    parts = line.split()
                    if len(parts) > 1:
                        return parts[1]

    except Exception as e:
        print(f"Error detecting gateway: {e}")

    return "192.168.1.1"  # Common default fallback

def test_port_connection(host, port, timeout=5):
    """Test TCP connection to a specific host and port."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        result = sock.connect_ex((host, port))
        sock.close()

        if result == 0:
            return True, f"Port {port} is OPEN"
        else:
            return False, f"Port {port} is CLOSED or FILTERED (error: {result})"

    except Exception as e:
        return False, f"Error testing port {port}: {str(e)}"

def main():
    print(f"Gateway Connection Test - {datetime.now().strftime('%Y-%m-%d %H:%M:%S %Z')}")
    print("=" * 50)

    # Get default gateway
    gateway = get_default_gateway()
    print(f"Default Gateway: {gateway}\n")

    # Ports to test
    ports = [8080, 8443, 3128]

    # Test each port
    successful_connections = 0
    total_ports = len(ports)

    for port in ports:
        print(f"Testing connection to {gateway}:{port}...")
        is_open, message = test_port_connection(gateway, port)
        print(f"  Result: {message}")

        if is_open:
            successful_connections += 1

        print()  # Empty line for readability

    # Summary
    print("Summary:")
    print(f"Successfully connected to {successful_connections}/{total_ports} ports")

    if successful_connections == 0:
        print("❌ No connections were successful. There may be network connectivity issues.")
        sys.exit(1)
    elif successful_connections < total_ports:
        print("⚠️  Partial connectivity. Some ports are blocked or services are down.")
        sys.exit(0)
    else:
        print("✅ All ports are accessible!")
        sys.exit(0)

if __name__ == "__main__":
    main()
